define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_41.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e176943","topics":[]},{"title":"Shutting down the host computer","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_42.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e177047","topics":[]},{"title":"Applying LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Apply LOTO to both the gradient and system Power Distribution Unit (PDU) breakers on the MDP when servicing either of these items in the ISC. Apply LOTO to make sure of a safe environment when working on these parts.<\/p>","href":"t_Applying-LOTO-ISC_38.html","attributes":{"data-id":"id_2001781"},"menu":{"hasChildren":false},"tocID":"id_2001781-d46e177151","topics":[]},{"title":"Opening the gradient Power Distribution Unit (PDU) top tray","shortdesc":"<p class=\"shortdesc\">Open the gradient PDU top tray to do troubleshooting or replacement tasks.<\/p>","href":"t_OpeningTheGradientPDUTopTray.html","attributes":{"data-id":"id_2006331"},"menu":{"hasChildren":false},"tocID":"id_2006331-d46e177255","topics":[]},{"title":"Removing the gradient Power Distribution Unit (PDU) AC contactor","shortdesc":"<p class=\"shortdesc\">Remove the AC contactor from the gradient PDU.<\/p>","href":"t_RemovingTheGradientPDUContactor.html","attributes":{"data-id":"id_2006259"},"menu":{"hasChildren":false},"tocID":"id_2006259-d46e177359","topics":[]},{"title":"Installing the gradient Power Distribution Unit (PDU) AC contactor","shortdesc":"<p class=\"shortdesc\">Install an AC contactor in the gradient PDU.<\/p>","href":"t_InstallingTheGradientPDUACContactor.html","attributes":{"data-id":"id_2006260"},"menu":{"hasChildren":false},"tocID":"id_2006260-d46e177463","topics":[]},{"title":"Closing the gradient Power Distribution Unit (PDU) top tray","shortdesc":"<p class=\"shortdesc\">Close the gradient PDU top tray after doing troubleshooting or replacement tasks.<\/p>","href":"t_ClosingTheGradientPDUTopTray.html","attributes":{"data-id":"id_2006332"},"menu":{"hasChildren":false},"tocID":"id_2006332-d46e177567","topics":[]},{"title":"Removing LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the gradient and system PDU breakers on the MDP before restoring power to the ISC.<\/p>","href":"t_Removing-LOTO-ISC_40.html","attributes":{"data-id":"id_2001783"},"menu":{"hasChildren":false},"tocID":"id_2001783-d46e177671","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_41.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e177775","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_65.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e177879","topics":[]}]});